import{_ as r,o as l,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2019-07-09 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-07-09 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-07-09T00:00:00.000Z","updated":"2019-07-12T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson存储引擎","CI/CD","错误处理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-09_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-07-09_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),t={name:"posts/2019/2019-07-09_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(e,i,g,_,p,a){return l(),o("div",null,[...i[0]||(i[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2019年7月9日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Crimson存储引擎讨论</strong></p><ul><li><strong>问题</strong>： Crimson存储引擎在处理大量客户端请求时，存在队列深度不足的问题，可能导致性能瓶颈。</li><li><strong>解决方案</strong>： 提高队列深度并增加客户端请求时间，以避免性能问题。</li><li><strong>关键点</strong>： 需要更新Crimson存储引擎，以支持更高的队列深度和客户端请求时间。</li></ul><p><strong>二、输入缓冲区工厂</strong></p><ul><li><strong>问题</strong>： 输入缓冲区工厂的细节讨论，特别是用户空间IP/TCP在Crimson中的实现。</li><li><strong>解决方案</strong>： <ul><li>研究内存复制操作在原生堆栈中的实现，特别是在运行助手应用程序时。</li><li>引入iommu和PTEs来提高安全性。</li><li>优化DMA和内存复制操作，以支持不同的硬件平台。</li></ul></li><li><strong>关键点</strong>： <ul><li>需要支持不同的DMA技术，如InfiniBand和RoCE。</li><li>需要抽象内存复制操作，以便在不同平台之间进行替换。</li></ul></li></ul><p><strong>三、CI/CD流程</strong></p><ul><li><strong>问题</strong>： Jenkins不支持CBT，且无法访问Pelagic。</li><li><strong>解决方案</strong>： <ul><li>创建本地CI/CD流程，使用Docker进行测试。</li><li>使用脚本启动和停止测试实例。</li></ul></li><li><strong>关键点</strong>： <ul><li>需要创建脚本，用于启动和停止测试实例。</li><li>需要选择合适的CI/CD工具。</li></ul></li></ul><p><strong>四、错误处理</strong></p><ul><li><strong>问题</strong>： 需要处理从对象存储传播的错误。</li><li><strong>解决方案</strong>： <ul><li>使用error handling primitives，如ignore和fork。</li><li>优化现有代码，以使用新的error handling primitives。</li></ul></li><li><strong>关键点</strong>： <ul><li>需要确定最佳的error handling strategy。</li><li>需要测试新的error handling primitives。</li></ul></li></ul><p><strong>五、其他</strong></p><ul><li><strong>Crimson协议</strong>： <ul><li>修复与Crimson消息传递相关的bug。</li><li>清理协议v2的日志。</li><li>理解握手过程。</li></ul></li><li><strong>工具</strong>： <ul><li>需要一个通用的工具，用于捕获和发送Crimson协议v2包。</li><li>需要一个Crimson协议v2的Wireshark插件。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li><strong>Crimson存储引擎</strong>： 更新Crimson存储引擎，以支持更高的队列深度和客户端请求时间。</li><li><strong>输入缓冲区工厂</strong>： 优化内存复制操作，支持不同的硬件平台。</li><li><strong>CI/CD流程</strong>： 创建本地CI/CD流程，使用Docker进行测试。</li><li><strong>错误处理</strong>： 确定最佳的error handling strategy，并优化现有代码。</li><li><strong>Crimson协议</strong>： 修复与Crimson消息传递相关的bug，清理协议v2的日志，理解握手过程。</li><li><strong>工具</strong>： 开发一个通用的工具，用于捕获和发送Crimson协议v2包，以及一个Crimson协议v2的Wireshark插件。</li></ul><p><strong>备注</strong>：</p><ul><li>部分计算机科学/ceph相关领域英文原文的关键词已保留在会议纪要中。</li><li>会议纪要已涵盖会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li></ul>",19)])])}const m=r(t,[["render",s]]);export{C as __pageData,m as default};
